function connectPort(port) {
  const handlersMap = new Map();
  return {
    postMessage: data => process.send({ port: port, data }),
    on: (event, handler) => {
      if (event !== "message") {
        throw new Error("Unsupported event: " + event);
      }
      const innerHandler = payload => {
        if (payload.port === port) {
          handler({ data: payload.data });
        }
      }
      handlersMap.set(handler, innerHandler);
      process.on('message', innerHandler);
    },
    off: (event, handler) => {
      if (event !== "message") {
        throw new Error("Unsupported event: " + event);
      }
      const innerHandler = handlersMap.get(handler);
      if (innerHandler) {
        process.off('message', innerHandler);
        handlersMap.delete(handler);
      }
    },
  };
}
